// Capture the completed jail UI after its panel has rendered. Origin is generated by w11-closure-proof.mjs.
import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {resolve,join} from 'node:path';
import {Session,serve} from '../playtest/lib.mjs';
const out=resolve('work/w11-closure'),server=await serve(resolve('.lane-builds/wave11-closure/dist'));
const session=await new Session({url:server.url,seed:7,wall:Date.UTC(2026,10,7),opTimeout:60000}).start();const result={viewport:'1920x1080',route:'fixture(just-ended constable encounter)'};
try{
 const save=JSON.parse(await fs.readFile(join(out,'private-origin.json'),'utf8'));save.expansion.simulation.log.push({at:save.expansion.clock,cause:'w11.fixture.ui.arrest',text:'Constables at the door: yielded.'});
 await session.open(save);await session.page.evaluate(()=>simulationTestHooks.project('tempo_fight'));
 await session.page.waitForFunction(()=>simulationTestHooks.project('constables').arrests===1&&!simulationTestHooks.project('constables').sentence);
 await session.page.locator('#workspace_navigation select').selectOption('lotm');
 await session.page.locator('#lotm_panel').waitFor({state:'visible'});
 await session.page.waitForFunction(()=>document.querySelector('#lotm_panel')?.innerText.includes('Tingen'));
 const snap=await session.page.evaluate(()=>simulationTestHooks.snapshot());assert.equal(snap.expansion.clock-save.expansion.clock,720);
 assert.match(await session.page.locator('#main_content').innerText(),/You spent 720 minutes in the cells|You spent the night in the cells/);
 await session.page.screenshot({path:join(out,'02-after-jail.png')});result.minutes=720;result.panelVisible=true;result.errors=session.errors;assert.deepEqual(result.errors,[]);result.ok=true;
}catch(e){result.ok=false;result.errors=session.errors;result.error=String(e.stack||e);}finally{await session.close();await server.close();}
await fs.writeFile(join(out,'jail-ui-result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));process.exit(result.ok?0:1);
